-- ══════════════════════════════════════════════════════════════════
-- Haveri Milk Union — Client Data Load Migration
-- 0018_load_client_data.sql
--
-- Imports two client-provided datasets:
--   1. Rate Chart (Base Price)        → products + price_chart
--   2. Officer-wise Agent List        → dealers
--
-- Source files (extracted from .pdf zips, 2026-04-27 export):
--   • Officer_wise_ag_list.pdf    (837 agents across 8 branches, 5 officers)
--   • rate_chart_base_price.pdf   (296 products × 4 rate categories)
--
-- Strategy:
--   • Add missing zones (Shiggaon, Rattihalli) seen in agent branches
--   • Soft-delete (deleted_at = now()) all existing products and dealers
--     — hard-delete is not safe due to FK references from orders/invoices
--   • Insert all products with base_price, gst, and per-category prices
--   • Re-populate price_chart (DELETE + INSERT — no FK dependents)
--   • Insert all agents as dealers, with placeholder phone numbers
--     (real phones in source PDF are scientific-notation rounded → unrecoverable)
--
-- Safety:
--   • Wrapped in a single transaction. Roll back on any error.
--   • Idempotent for zones (ON CONFLICT (slug) DO NOTHING)
--   • Idempotent for time_windows (ON CONFLICT (zone_id) DO NOTHING)
--
-- Run with: psql $DATABASE_URL -f 0018_load_client_data.sql
-- ══════════════════════════════════════════════════════════════════

BEGIN;

-- ┌─────────────────────────────────────────┐
-- │  STEP 1 — Add missing zones              │
-- └─────────────────────────────────────────┘
-- Branches present in agent data but missing from existing zones table:
--   • SHIGGAON  → Shiggaon (Haveri district town, ~28km from HQ)
--   • RATTIHALLI → Rattihalli (Haveri district town, ~30km from HQ)

ON CONFLICT (slug) DO NOTHING;

SELECT z.id, '06:00'::time, 20, '08:00'::time
FROM zones z
WHERE z.slug IN ('shiggaon', 'rattihalli')
ON CONFLICT (zone_id) DO NOTHING;



-- ┌─────────────────────────────────────────┐
-- │  STEP 2 — Rate Chart → products          │
-- └─────────────────────────────────────────┘
-- Soft-delete existing products. Hard-delete impossible: FKs from
-- order_items, price_revisions, fgs_stock_log, direct_sale_items, etc.

UPDATE products SET deleted_at = now() WHERE deleted_at IS NULL;

-- Wipe price_chart (no FK dependents) — will be repopulated below.
DELETE FROM price_chart;

-- Reset per-category price columns on products (will be re-set on INSERT).
-- Note: the previous UPDATE soft-deleted them, but in case any are kept
-- alive from a backout, also clear values:
UPDATE products SET
  retail_dealer_price      = NULL,
  credit_inst_mrp_price    = NULL,
  credit_inst_dealer_price = NULL,
  parlour_dealer_price     = NULL
WHERE deleted_at IS NOT NULL;

-- Insert all products. 296 distinct rows from the rate chart.



-- Insert price_chart entries: one row per (product × category) where a price
-- was provided in the rate chart. effective_from = today (data load date).



-- ┌─────────────────────────────────────────┐
-- │  STEP 3 — Officer-wise Agent List        │
-- └─────────────────────────────────────────┘
-- Soft-delete existing dealers. Hard delete impossible: FKs from orders,
-- invoices, dealer_wallets, dealer_ledger, payments, etc.
--
-- NOTE on phone numbers:
--   The source PDF rendered phone numbers in scientific notation
--   ("8.2E+09", "9.45E+09"), losing the trailing digits. Real phone
--   numbers are unrecoverable from this dataset. We insert placeholder
--   phones in the form "PENDING-{agent_id}" — these MUST be replaced
--   with real numbers via the dealer registration / app sign-up flow
--   before OTP-based login can work for these agents.
--
-- The dealers.phone column is "text NOT NULL UNIQUE", so the placeholder
-- format keeps the constraint satisfied without colliding with real phones.

UPDATE dealers SET active = false, deleted_at = now() WHERE deleted_at IS NULL;



-- Create wallet rows for newly inserted dealers (one per dealer).
SELECT d.id, 0
FROM dealers d
LEFT JOIN dealer_wallets w ON w.dealer_id = d.id
WHERE d.deleted_at IS NULL AND w.id IS NULL;

-- ┌─────────────────────────────────────────┐
-- │  STEP 4 — Verification queries           │
-- └─────────────────────────────────────────┘
-- These RAISE NOTICEs print a quick summary so you can sanity-check
-- the import before COMMIT-ing. Adjust thresholds for your dataset.

DO $$
DECLARE
  v_active_products integer;
  v_pricechart_rows integer;
  v_active_dealers  integer;
BEGIN
  SELECT count(*) INTO v_active_products FROM products WHERE deleted_at IS NULL;
  SELECT count(*) INTO v_pricechart_rows FROM price_chart;
  SELECT count(*) INTO v_active_dealers  FROM dealers  WHERE deleted_at IS NULL;

  RAISE NOTICE 'Import summary:';
  RAISE NOTICE '  Active products: %  (expected ~296)', v_active_products;
  RAISE NOTICE '  Price-chart rows: % (expected ~1075)', v_pricechart_rows;
  RAISE NOTICE '  Active dealers:  %  (expected ~835)',  v_active_dealers;

  -- Hard-fail if numbers are way off
  IF v_active_products < 250 THEN
    RAISE EXCEPTION 'Product count too low: % — aborting', v_active_products;
  END IF;
  IF v_active_dealers < 700 THEN
    RAISE EXCEPTION 'Dealer count too low: % — aborting',  v_active_dealers;
  END IF;
END $$;

COMMIT;

-- ══════════════════════════════════════════════════════════════════
-- Migration 0018 complete. Loaded:
-- ✓ 2 new zones (Shiggaon, Rattihalli) with default time-windows
-- ✓ Soft-deleted prior products and dealers (deleted_at = now())
-- ✓ ~296 products with base price, GST, and 4 per-category prices
-- ✓ ~1075 price_chart rows (one per product × applicable category)
-- ✓ ~835 dealers with code, zone, officer assignment
--   — NOTE: phone numbers are placeholders ("PENDING-<id>") and
--     must be updated with real numbers before OTP login works.
-- ══════════════════════════════════════════════════════════════════
